/**
 * Cloudflare Worker entrypoint.
 *
 * Wraps the handler generated by `@opennextjs/cloudflare` (which only exports
 * `fetch`) so the Worker can also answer Cloudflare Cron Triggers.
 *
 * Why this file is needed: Vercel Cron invoked cron jobs by *fetching a path*,
 * so the three jobs live as route handlers under `/api/mkt/cron/*`. Cloudflare
 * instead invokes a `scheduled()` export on the Worker. Without this wrapper the
 * triggers declared in wrangler.jsonc would fire into a Worker that has no
 * `scheduled` handler — registered, but silently doing nothing, which is worse
 * than having no schedule at all.
 *
 * `scheduled()` dispatches straight into the same fetch handler rather than
 * making a real network request, so the work runs in-isolate with no extra hop
 * and no dependency on the public hostname resolving from inside the Worker.
 * The request is signed with `CRON_SECRET`, exactly as Vercel Cron did, so the
 * route's existing bearer check is unchanged and still rejects anything unsigned.
 */
import openNext from "./.open-next/worker.js";

/**
 * Cron expression -> route. Keys must match `triggers.crons` in wrangler.jsonc
 * exactly; Cloudflare passes the matched expression as `event.cron`.
 */
const CRON_ROUTES = {
  "0 * * * *": "/api/mkt/cron/process-outreach",
  "15 * * * *": "/api/mkt/cron/process-content",
  "30 * * * *": "/api/mkt/cron/sync-sourcing",
};

const FALLBACK_ORIGIN = "https://move37-operational-system.f3importers.workers.dev";

export default {
  fetch(request, env, ctx) {
    return openNext.fetch(request, env, ctx);
  },

  async scheduled(event, env, ctx) {
    const path = CRON_ROUTES[event.cron];
    if (!path) {
      // A trigger was added to wrangler.jsonc without a matching route here.
      console.error(`[cron] no route mapped for expression "${event.cron}"`);
      return;
    }

    const secret = env.CRON_SECRET;
    if (!secret) {
      // Fail loudly: the route would reject the call anyway, and a silent
      // no-op here would look like a cron that ran successfully.
      console.error(`[cron] CRON_SECRET is not set; skipping ${path}`);
      return;
    }

    const origin = env.NEXT_PUBLIC_APP_URL || FALLBACK_ORIGIN;
    const request = new Request(`${origin.replace(/\/$/, "")}${path}`, {
      method: "GET",
      headers: { Authorization: `Bearer ${secret}` },
    });

    try {
      const response = await openNext.fetch(request, env, ctx);
      const body = await response.text();
      if (!response.ok) {
        console.error(`[cron] ${path} -> ${response.status} ${body.slice(0, 300)}`);
      } else {
        console.log(`[cron] ${path} -> ${response.status}`);
      }
    } catch (error) {
      console.error(`[cron] ${path} threw`, error);
    }
  },
};
